package main

import (
	"flag"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"sync"
	"sync/atomic"
	"time"
)

// Downloader 下载器结构体
type Downloader struct {
	URL          string        // 下载链接
	Output       string        // 输出文件名
	Threads      int           // 并发线程数
	FileSize     int64         // 文件总大小
	TempDir      string        // 临时文件目录
	TempFiles    []string      // 临时文件列表
	progress     uint64        // 已下载字节数（原子操作）
	progressMu   sync.Mutex    // 进度显示锁
	stopProgress chan struct{} // 停止进度显示的通道
}

// NewDownloader 创建下载器实例
func NewDownloader(url, output string, threads int) (*Downloader, error) {
	// 创建临时目录（基于输出文件的目录）
	outputDir := filepath.Dir(output)
	tempDir, err := os.MkdirTemp(outputDir, "download_temp_*")
	if err != nil {
		return nil, fmt.Errorf("创建临时目录失败: %v", err)
	}

	return &Downloader{
		URL:          url,
		Output:       output,
		Threads:      threads,
		TempDir:      tempDir,
		stopProgress: make(chan struct{}),
	}, nil
}

// CheckServerSupport 检查服务器是否支持分段下载并获取文件大小
func (d *Downloader) CheckServerSupport() error {
	req, err := http.NewRequest("HEAD", d.URL, nil)
	if err != nil {
		return fmt.Errorf("创建HEAD请求失败: %v", err)
	}

	// 设置超时
	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("发送HEAD请求失败: %v", err)
	}
	defer resp.Body.Close()

	// 检查响应状态
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("服务器返回错误状态码: %d", resp.StatusCode)
	}

	// 获取文件大小
	d.FileSize = resp.ContentLength
	if d.FileSize <= 0 {
		fmt.Println("警告：无法获取文件大小，将使用单线程流式下载")
		d.Threads = 1
		return nil
	}

	// 检查是否支持分段下载
	acceptRanges := resp.Header.Get("Accept-Ranges")
	if acceptRanges != "bytes" {
		fmt.Println("警告：服务器不支持分段下载，将使用单线程下载")
		d.Threads = 1
	}

	fmt.Printf("文件大小: %.2f MB\n", float64(d.FileSize)/(1024*1024))
	fmt.Printf("并发线程数: %d\n", d.Threads)
	return nil
}

// DownloadSegment 下载单个文件分段
func (d *Downloader) DownloadSegment(start, end int64, index int, wg *sync.WaitGroup) error {
	defer wg.Done()

	// 临时文件名
	tempFile := filepath.Join(d.TempDir, fmt.Sprintf("segment_%d", index))
	d.TempFiles = append(d.TempFiles, tempFile)

	// 创建临时文件
	f, err := os.Create(tempFile)
	if err != nil {
		return fmt.Errorf("创建临时文件 %s 失败: %v", tempFile, err)
	}
	defer f.Close()

	// 构造Range请求头
	req, err := http.NewRequest("GET", d.URL, nil)
	if err != nil {
		return fmt.Errorf("创建GET请求失败: %v", err)
	}
	req.Header.Set("Range", fmt.Sprintf("bytes=%d-%d", start, end))

	// 发送请求
	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return fmt.Errorf("下载分段 %d 失败: %v", index, err)
	}
	defer resp.Body.Close()

	// 检查分段响应状态
	if resp.StatusCode != http.StatusPartialContent && d.Threads > 1 {
		return fmt.Errorf("分段 %d 下载失败，服务器返回状态码: %d", index, resp.StatusCode)
	}

	// 读取并写入文件，同时更新进度
	buf := make([]byte, 4096)
	for {
		n, err := resp.Body.Read(buf)
		if n > 0 {
			if _, err := f.Write(buf[:n]); err != nil {
				return fmt.Errorf("写入临时文件 %s 失败: %v", tempFile, err)
			}
			// 原子更新已下载字节数
			atomic.AddUint64(&d.progress, uint64(n))
		}
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("读取分段 %d 数据失败: %v", index, err)
		}
	}

	return nil
}

// MergeSegments 合并所有分段文件
func (d *Downloader) MergeSegments() error {
	// 创建最终输出文件
	outFile, err := os.Create(d.Output)
	if err != nil {
		return fmt.Errorf("创建输出文件 %s 失败: %v", d.Output, err)
	}
	defer outFile.Close()

	// 按顺序合并每个分段
	for _, tempFile := range d.TempFiles {
		f, err := os.Open(tempFile)
		if err != nil {
			return fmt.Errorf("打开临时文件 %s 失败: %v", tempFile, err)
		}
		// 复制文件内容
		if _, err := io.Copy(outFile, f); err != nil {
			f.Close()
			return fmt.Errorf("合并临时文件 %s 失败: %v", tempFile, err)
		}
		f.Close()
	}

	return nil
}

// ShowProgress 实时显示下载进度
func (d *Downloader) ShowProgress() {
	ticker := time.NewTicker(500 * time.Millisecond)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			d.progressMu.Lock()
			if d.FileSize <= 0 {
				fmt.Printf("\r已下载: %.2f MB (未知总大小)", float64(atomic.LoadUint64(&d.progress))/(1024*1024))
			} else {
				percent := float64(atomic.LoadUint64(&d.progress)) / float64(d.FileSize) * 100
				fmt.Printf("\r已下载: %.2f MB / %.2f MB (%.2f%%)",
					float64(atomic.LoadUint64(&d.progress))/(1024*1024),
					float64(d.FileSize)/(1024*1024),
					percent)
			}
			d.progressMu.Unlock()
		case <-d.stopProgress:
			// 最终进度显示
			d.progressMu.Lock()
			if d.FileSize > 0 {
				percent := float64(atomic.LoadUint64(&d.progress)) / float64(d.FileSize) * 100
				fmt.Printf("\r已下载: %.2f MB / %.2f MB (%.2f%%)\n",
					float64(atomic.LoadUint64(&d.progress))/(1024*1024),
					float64(d.FileSize)/(1024*1024),
					percent)
			} else {
				fmt.Printf("\r已下载: %.2f MB (未知总大小)\n", float64(atomic.LoadUint64(&d.progress))/(1024*1024))
			}
			d.progressMu.Unlock()
			return
		}
	}
}

// Cleanup 清理临时文件和目录
func (d *Downloader) Cleanup() {
	// 关闭进度显示
	close(d.stopProgress)

	// 删除临时文件
	for _, f := range d.TempFiles {
		os.Remove(f)
	}
	// 删除临时目录
	os.RemoveAll(d.TempDir)
}

// Download 执行下载流程
func (d *Downloader) Download() error {
	defer d.Cleanup()

	// 检查服务器支持
	if err := d.CheckServerSupport(); err != nil {
		return err
	}

	// 启动进度显示goroutine
	go d.ShowProgress()

	// 单线程下载（不支持分段或文件大小未知）
	if d.Threads == 1 {
		var wg sync.WaitGroup
		wg.Add(1)
		err := d.DownloadSegment(0, d.FileSize-1, 0, &wg)
		wg.Wait()
		if err != nil {
			return err
		}
	} else {
		// 多线程分段下载：计算每个分段的起始和结束位置
		segmentSize := d.FileSize / int64(d.Threads)
		var wg sync.WaitGroup

		for i := 0; i < d.Threads; i++ {
			start := int64(i) * segmentSize
			end := start + segmentSize - 1

			// 最后一个分段处理剩余部分
			if i == d.Threads-1 {
				end = d.FileSize - 1
			}

			wg.Add(1)
			go func(idx int, s, e int64) {
				if err := d.DownloadSegment(s, e, idx, &wg); err != nil {
					fmt.Printf("\n分段 %d 下载失败: %v\n", idx, err)
					// 这里可以扩展为重试逻辑
					os.Exit(1)
				}
			}(i, start, end)
		}

		// 等待所有分段下载完成
		wg.Wait()
	}

	// 合并分段文件
	fmt.Println("\n开始合并分段文件...")
	if err := d.MergeSegments(); err != nil {
		return fmt.Errorf("合并分段失败: %v", err)
	}

	fmt.Printf("下载完成！文件已保存至: %s\n", d.Output)
	return nil
}

func main() {
	// 解析命令行参数
	url := flag.String("url", "", "下载链接（必填）")
	output := flag.String("output", "download_file", "输出文件名（可选，默认download_file）")
	threads := flag.Int("threads", 5, "并发下载线程数（可选，默认5）")
	flag.Parse()

	// 校验必填参数
	if *url == "" {
		fmt.Println("错误：必须指定下载链接（-url 参数）")
		flag.Usage()
		os.Exit(1)
	}

	// 限制线程数范围
	if *threads < 1 || *threads > 20 {
		fmt.Println("警告：线程数超出合理范围（1-20），自动调整为5")
		*threads = 5
	}

	// 创建下载器并执行下载
	downloader, err := NewDownloader(*url, *output, *threads)
	if err != nil {
		fmt.Printf("初始化下载器失败: %v\n", err)
		os.Exit(1)
	}

	if err := downloader.Download(); err != nil {
		fmt.Printf("下载失败: %v\n", err)
		os.Exit(1)
	}
}

