func (d *Downloader) Download() error {
	defer d.Cleanup()

	// 检查服务器支持
	if err := d.CheckServerSupport(); err != nil {
		return err
	}

	// 启动进度显示goroutine
	go d.ShowProgress()

	// 单线程下载（不支持分段或文件大小未知）
	if d.Threads == 1 {
		var wg sync.WaitGroup
		wg.Add(1)
		err := d.DownloadSegment(0, d.FileSize-1, 0, &wg)
		wg.Wait()
		if err != nil {
			return err
		}
	} else {
		// 多线程分段下载：计算每个分段的起始和结束位置
		segmentSize := d.FileSize / int64(d.Threads)
		var wg sync.WaitGroup

		for i := 0; i < d.Threads; i++ {
			start := int64(i) * segmentSize
			end := start + segmentSize - 1

			// 最后一个分段处理剩余部分
			if i == d.Threads-1 {
				end = d.FileSize - 1
			}

			wg.Add(1)
			go func(idx int, s, e int64) {
				if err := d.DownloadSegment(s, e, idx, &wg); err != nil {
					fmt.Printf("\n分段 %d 下载失败: %v\n", idx, err)
					// 这里可以扩展为重试逻辑
					os.Exit(1)
				}
			}(i, start, end)
		}

		// 等待所有分段下载完成
		wg.Wait()
	}

	// 合并分段文件
	fmt.Println("\n开始合并分段文件...")
	if err := d.MergeSegments(); err != nil {
		return fmt.Errorf("合并分段失败: %v", err)
	}

	fmt.Printf("下载完成！文件已保存至: %s\n", d.Output)
	return nil
}","new_string":"// Download 执行下载流程
func (d *Downloader) Download() error {
	defer d.Cleanup()

	// 记录开始时间
	d.startTime = time.Now()

	// 检查服务器支持
	fmt.Println("正在检查服务器支持...")
	if err := d.CheckServerSupport(); err != nil {
		return err
	}

	// 启动进度显示goroutine
	go d.ShowProgress()

	// 单线程下载（不支持分段或文件大小未知）
	if d.Threads == 1 {
		fmt.Println("开始单线程下载...")
		var wg sync.WaitGroup
		wg.Add(1)
		err := d.DownloadSegment(0, d.FileSize-1, 0, &wg)
		wg.Wait()
		if err != nil {
			return fmt.Errorf("下载失败: %v", err)
		}
	} else {
		// 多线程分段下载：计算每个分段的起始和结束位置
		fmt.Printf("开始 %d 线程并发下载...\n", d.Threads)
		segmentSize := d.FileSize / int64(d.Threads)
		var wg sync.WaitGroup
		errChan := make(chan error, d.Threads)

		for i := 0; i < d.Threads; i++ {
			start := int64(i) * segmentSize
			end := start + segmentSize - 1

			// 最后一个分段处理剩余部分
			if i == d.Threads-1 {
				end = d.FileSize - 1
			}

			wg.Add(1)
			go func(idx int, s, e int64) {
				if err := d.DownloadSegment(s, e, idx, &wg); err != nil {
					fmt.Printf("\n分段 %d 下载失败: %v\n", idx, err)
					errChan <- err
					d.cancel() // 取消其他下载
				}
			}(i, start, end)
		}

		// 等待所有分段下载完成
		wg.Wait()
		close(errChan)

		// 检查是否有错误
		if len(errChan) > 0 {
			return <-errChan
		}
	}

	// 检查是否有错误
	d.errorsMu.Lock()
	hasErrors := len(d.errors) > 0
	d.errorsMu.Unlock()

	if hasErrors {
		return fmt.Errorf("下载过程中出现错误，请查看上方日志")
	}

	// 合并分段文件
	fmt.Println("\n开始合并分段文件...")
	if err := d.MergeSegments(); err != nil {
		return fmt.Errorf("合并分段失败: %v", err)
	}

	// 验证文件大小
	if d.FileSize > 0 {
		fileInfo, err := os.Stat(d.Output)
		if err != nil {
			fmt.Printf("警告：无法验证文件大小: %v\n", err)
		} else if fileInfo.Size() != d.FileSize {
			return fmt.Errorf("文件大小不匹配：期望 %d 字节，实际 %d 字节", d.FileSize, fileInfo.Size())
		}
	}

	fmt.Printf("\n✓ 下载完成！文件已保存至: %s\n", d.Output)
	return nil
}"},{"old_string":"func main() {
