import (
	"context"
	"encoding/json"
	"fmt"
	"html/template"
	"log"
	"net/http"
	"os"
	"sync"
	"sync/atomic"
	"time"

	"github.com/gorilla/websocket"
)

// UIDownloader Web UI版本的下载器
type UIDownloader struct {
	*Downloader
	wsClients   map[*websocket.Conn]bool
	wsClientsMu sync.Mutex
	broadcast   chan ProgressMessage
}

// ProgressMessage 进度消息
type ProgressMessage struct {
	Type       string  `json:"type"`
	Downloaded float64 `json:"downloaded"`
	Total      float64 `json:"total"`
	Percent    float64 `json:"percent"`
	Speed      float64 `json:"speed"`
	ETA        string  `json:"eta"`
	Status     string  `json:"status"`
	Message    string  `json:"message"`
	AvgSpeed   float64 `json:"avgSpeed,omitempty"`
	TotalTime  string  `json:"totalTime,omitempty"`
	OutputFile string  `json:"outputFile,omitempty"`
}

// DownloadRequest 下载请求
type DownloadRequest struct {
	URL     string `json:"url"`
	Output  string `json:"output"`
	Threads int    `json:"threads"`
	Retry   int    `json:"retry"`
	Timeout int    `json:"timeout"`
}

var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool {
		return true // 允许所有来源
	},
}

// NewUIDownloader 创建UI下载器
func NewUIDownloader(url, output string, threads int) (*UIDownloader, error) {
	d, err := NewDownloader(url, output, threads)
	if err != nil {
		return nil, err
	}

	return &UIDownloader{
		Downloader: d,
		wsClients:  make(map[*websocket.Conn]bool),
		broadcast:  make(chan ProgressMessage, 100),
	}, nil
}

// ShowProgressUI 实时显示下载进度并通过WebSocket推送
func (d *UIDownloader) ShowProgressUI() {
	ticker := time.NewTicker(500 * time.Millisecond)
	defer ticker.Stop()

	lastProgress := uint64(0)
	lastTime := time.Now()

	for {
		select {
		case <-ticker.C:
			d.Downloader.progressMu.Lock()
			currentProgress := atomic.LoadUint64(&d.Downloader.progress)
			currentTime := time.Now()
			elapsed := currentTime.Sub(lastTime).Seconds()

			// 计算下载速度
			speed := float64(0)
			if elapsed > 0 {
				speed = float64(currentProgress-lastProgress) / elapsed / 1024 / 1024 // MB/s
			}

			msg := ProgressMessage{
				Type:       "progress",
				Downloaded: float64(currentProgress) / (1024 * 1024),
				Status:     "downloading",
			}

			if d.Downloader.FileSize > 0 {
				msg.Total = float64(d.Downloader.FileSize) / (1024 * 1024)
				msg.Percent = float64(currentProgress) / float64(d.Downloader.FileSize) * 100
				msg.Speed = speed

				// 计算预计剩余时间
				if speed > 0 {
					remaining := float64(d.Downloader.FileSize-int64(currentProgress)) / (speed * 1024 * 1024)
					msg.ETA = formatDuration(time.Duration(remaining) * time.Second)
				}
			} else {
				msg.Speed = speed
			}

			d.broadcast <- msg

			lastProgress = currentProgress
			lastTime = currentTime
			d.Downloader.progressMu.Unlock()

		case <-d.Downloader.stopProgress:
			// 最终进度显示
			d.Downloader.progressMu.Lock()
			currentProgress := atomic.LoadUint64(&d.Downloader.progress)
			totalTime := time.Since(d.Downloader.startTime)
			avgSpeed := float64(currentProgress) / totalTime.Seconds() / 1024 / 1024

			msg := ProgressMessage{
				Type:       "complete",
				Downloaded: float64(currentProgress) / (1024 * 1024),
				Status:     "completed",
				AvgSpeed:   avgSpeed,
				TotalTime:  formatDuration(totalTime),
				OutputFile: d.Downloader.Output,
			}

			if d.Downloader.FileSize > 0 {
				msg.Total = float64(d.Downloader.FileSize) / (1024 * 1024)
				msg.Percent = 100
			}

			d.broadcast <- msg
			d.Downloader.progressMu.Unlock()
			return
		}
	}
}

// BroadcastMessages 广播消息到所有WebSocket客户端
func (d *UIDownloader) BroadcastMessages() {
	for msg := range d.broadcast {
		d.wsClientsMu.Lock()
		for client := range d.wsClients {
			err := client.WriteJSON(msg)
			if err != nil {
				client.Close()
				delete(d.wsClients, client)
			}
		}
		d.wsClientsMu.Unlock()
	}
}

// DownloadUI 执行下载流程（UI版本）
func (d *UIDownloader) DownloadUI() error {
	defer d.Downloader.Cleanup()

	// 记录开始时间
	d.Downloader.startTime = time.Now()

	// 发送开始消息
	d.broadcast <- ProgressMessage{
		Type:    "info",
		Status:  "checking",
		Message: "正在检查服务器支持...",
	}

	// 检查服务器支持
	if err := d.Downloader.CheckServerSupport(); err != nil {
		d.broadcast <- ProgressMessage{
			Type:    "error",
			Status:  "failed",
			Message: fmt.Sprintf("检查服务器失败: %v", err),
		}
		return err
	}

	d.broadcast <- ProgressMessage{
		Type:    "info",
		Status:  "starting",
		Message: fmt.Sprintf("开始下载，文件大小: %.2f MB，线程数: %d", float64(d.Downloader.FileSize)/(1024*1024), d.Downloader.Threads),
	}

	// 启动进度显示goroutine
	go d.ShowProgressUI()

	// 单线程下载
	if d.Downloader.Threads == 1 {
		var wg sync.WaitGroup
		wg.Add(1)
		err := d.Downloader.DownloadSegment(0, d.Downloader.FileSize-1, 0, &wg)
		wg.Wait()
		if err != nil {
			d.broadcast <- ProgressMessage{
				Type:    "error",
				Status:  "failed",
				Message: fmt.Sprintf("下载失败: %v", err),
			}
			return fmt.Errorf("下载失败: %v", err)
		}
	} else {
		// 多线程分段下载
		segmentSize := d.Downloader.FileSize / int64(d.Downloader.Threads)
		var wg sync.WaitGroup
		errChan := make(chan error, d.Downloader.Threads)

		for i := 0; i < d.Downloader.Threads; i++ {
			start := int64(i) * segmentSize
			end := start + segmentSize - 1

			if i == d.Downloader.Threads-1 {
				end = d.Downloader.FileSize - 1
			}

			wg.Add(1)
			go func(idx int, s, e int64) {
				if err := d.Downloader.DownloadSegment(s, e, idx, &wg); err != nil {
					errChan <- err
					d.Downloader.cancel()
				}
			}(i, start, end)
		}

		wg.Wait()
		close(errChan)

		if len(errChan) > 0 {
			err := <-errChan
			d.broadcast <- ProgressMessage{
				Type:    "error",
				Status:  "failed",
				Message: fmt.Sprintf("下载失败: %v", err),
			}
			return err
		}
	}

	// 检查错误
	d.Downloader.errorsMu.Lock()
	hasErrors := len(d.Downloader.errors) > 0
	d.Downloader.errorsMu.Unlock()

	if hasErrors {
		d.broadcast <- ProgressMessage{
			Type:    "error",
			Status:  "failed",
			Message: "下载过程中出现错误",
		}
		return fmt.Errorf("下载过程中出现错误")
	}

	// 合并分段文件
	d.broadcast <- ProgressMessage{
		Type:    "info",
		Status:  "merging",
		Message: "正在合并分段文件...",
	}

	if err := d.Downloader.MergeSegments(); err != nil {
		d.broadcast <- ProgressMessage{
			Type:    "error",
			Status:  "failed",
			Message: fmt.Sprintf("合并分段失败: %v", err),
		}
		return fmt.Errorf("合并分段失败: %v", err)
	}

	// 验证文件大小
	if d.Downloader.FileSize > 0 {
		fileInfo, err := os.Stat(d.Downloader.Output)
		if err == nil && fileInfo.Size() != d.Downloader.FileSize {
			d.broadcast <- ProgressMessage{
				Type:    "error",
				Status:  "failed",
				Message: fmt.Sprintf("文件大小不匹配：期望 %d 字节，实际 %d 字节", d.Downloader.FileSize, fileInfo.Size()),
			}
			return fmt.Errorf("文件大小不匹配")
		}
	}

	return nil
}

// HTML模板
const htmlTemplate = `
<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Go 多线程下载工具</title>
    <style>
        * {
            margin: 0;
            padding: 0;
