    </style>
</head>
<body>
    <div class="container">
        <h1> Go 多线程下载工具</h1>
        <p class="subtitle">高速、稳定、支持断点续传</p>

        <form id="downloadForm">
            <div class="form-group">
                <label for="url">下载链接 *</label>
                <input type="text" id="url" name="url" placeholder="https://example.com/file.zip" required>
            </div>

            <div class="form-group">
                <label for="output">输出文件名</label>
                <input type="text" id="output" name="output" placeholder="download_file" value="download_file">
            </div>

            <div class="row">
                <div class="form-group">
                    <label for="threads">线程数</label>
                    <input type="number" id="threads" name="threads" min="1" max="20" value="5">
                </div>

                <div class="form-group">
                    <label for="retry">重试次数</label>
                    <input type="number" id="retry" name="retry" min="0" max="10" value="3">
                </div>

                <div class="form-group">
                    <label for="timeout">超时(秒)</label>
                    <input type="number" id="timeout" name="timeout" min="5" max="300" value="30">
                </div>
            </div>

            <button type="submit" id="downloadBtn">开始下载</button>
        </form>

        <div class="progress-container" id="progressContainer">
            <div class="progress-bar-bg">
                <div class="progress-bar" id="progressBar">0%</div>
            </div>
            <div class="progress-info" id="progressInfo">
                <div>已下载: <strong id="downloaded">0 MB</strong> / <strong id="total">0 MB</strong></div>
                <div>下载速度: <strong id="speed">0 MB/s</strong></div>
                <div>预计剩余: <strong id="eta">计算中...</strong></div>
            </div>
        </div>

        <div id="statusContainer"></div>
    </div>

    <script>
        const form = document.getElementById('downloadForm');
        const downloadBtn = document.getElementById('downloadBtn');
        const progressContainer = document.getElementById('progressContainer');
        const progressBar = document.getElementById('progressBar');
        const statusContainer = document.getElementById('statusContainer');

        let ws = null;

        form.addEventListener('submit', async (e) => {
            e.preventDefault();

            const formData = {
                url: document.getElementById('url').value,
                output: document.getElementById('output').value,
                threads: parseInt(document.getElementById('threads').value),
                retry: parseInt(document.getElementById('retry').value),
                timeout: parseInt(document.getElementById('timeout').value)
            };

            // 禁用按钮
            downloadBtn.disabled = true;
            downloadBtn.innerHTML = '<span class="spinner"></span>正在下载...';

            // 显示进度条
            progressContainer.style.display = 'block';
            statusContainer.innerHTML = '';

            // 连接WebSocket
            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            ws = new WebSocket(protocol + '//' + window.location.host + '/ws');

            ws.onmessage = (event) => {
                const msg = JSON.parse(event.data);
                handleProgressMessage(msg);
            };

            ws.onerror = () => {
                showStatus('WebSocket连接错误', 'error');
            };

            ws.onclose = () => {
                downloadBtn.disabled = false;
                downloadBtn.textContent = '开始下载';
            };

            // 发送下载请求
            try {
                const response = await fetch('/download', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(formData)
                });

                const result = await response.json();
                if (!response.ok) {
                    showStatus(result.error || '下载失败', 'error');
                }
            } catch (error) {
                showStatus('请求失败: ' + error.message, 'error');
            }
        });

        function handleProgressMessage(msg) {
            if (msg.type === 'progress') {
                const percent = msg.percent || 0;
                progressBar.style.width = percent + '%';
                progressBar.textContent = percent.toFixed(1) + '%';

                document.getElementById('downloaded').textContent = msg.downloaded.toFixed(2) + ' MB';
                document.getElementById('total').textContent = msg.total ? msg.total.toFixed(2) + ' MB' : '未知';
                document.getElementById('speed').textContent = msg.speed.toFixed(2) + ' MB/s';
                document.getElementById('eta').textContent = msg.eta || '计算中...';
            } else if (msg.type === 'complete') {
                progressBar.style.width = '100%';
                progressBar.textContent = '100%';
                showStatus('✓ 下载完成！文件已保存至: ' + msg.outputFile + ' (平均速度: ' + msg.avgSpeed.toFixed(2) + ' MB/s, 总耗时: ' + msg.totalTime + ')', 'success');
                if (ws) ws.close();
            } else if (msg.type === 'error') {
                showStatus('✗ ' + msg.message, 'error');
                if (ws) ws.close();
            } else if (msg.type === 'info') {
                showStatus(msg.message, 'info');
            }
        }

        function showStatus(message, type) {
            const statusDiv = document.createElement('div');
            statusDiv.className = 'status ' + type;
            statusDiv.textContent = message;
            statusContainer.innerHTML = '';
            statusContainer.appendChild(statusDiv);
        }
    </script>
</body>
</html>
`

// 处理首页
func handleIndex(w http.ResponseWriter, r *http.Request) {
	tmpl := template.Must(template.New("index").Parse(htmlTemplate))
	tmpl.Execute(w, nil)
}

// 处理WebSocket连接
func handleWebSocket(w http.ResponseWriter, r *http.Request, clients *map[*websocket.Conn]bool, mu *sync.Mutex) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		log.Println("WebSocket升级失败:", err)
		return
	}

	mu.Lock()
	(*clients)[conn] = true
	mu.Unlock()

	// 保持连接
	defer func() {
		mu.Lock()
		delete(*clients, conn)
		mu.Unlock()
		conn.Close()
	}()

	for {
		_, _, err := conn.ReadMessage()
		if err != nil {
			break
		}
	}
}

// 处理下载请求
func handleDownload(w http.ResponseWriter, r *http.Request, clients *map[*websocket.Conn]bool, mu *sync.Mutex) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	var req DownloadRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		json.NewEncoder(w).Encode(map[string]string{"error": "无效的请求数据"})
		return
	}

	// 验证参数
	if req.URL == "" {
		json.NewEncoder(w).Encode(map[string]string{"error": "URL不能为空"})
		return
	}
	if req.Threads < 1 || req.Threads > 20 {
		req.Threads = 5
	}
	if req.Retry < 0 || req.Retry > 10 {
		req.Retry = 3
	}
	if req.Timeout < 5 || req.Timeout > 300 {
		req.Timeout = 30
	}
	if req.Output == "" {
		req.Output = "download_file"
	}

	// 创建下载器
	downloader, err := NewUIDownloader(req.URL, req.Output, req.Threads)
	if err != nil {
		json.NewEncoder(w).Encode(map[string]string{"error": err.Error()})
		return
	}

	downloader.Downloader.retryCount = req.Retry
	downloader.Downloader.timeout = time.Duration(req.Timeout) * time.Second
	downloader.Downloader.client.Timeout = downloader.Downloader.timeout

	// 共享WebSocket客户端
	downloader.wsClients = *clients
	downloader.wsClientsMu = *mu

	// 启动广播goroutine
	go downloader.BroadcastMessages()

	// 异步执行下载
	go func() {
		if err := downloader.DownloadUI(); err != nil {
			log.Printf("下载失败: %v\n", err)
		}
	}()

	json.NewEncoder(w).Encode(map[string]string{"status": "started"})
}

func main() {
	// 检查是否使用UI模式
	if len(os.Args) > 1 && os.Args[1] == "ui" {
		port := "8080"
		if len(os.Args) > 2 {
			port = os.Args[2]
		}

		clients := make(map[*websocket.Conn]bool)
		var mu sync.Mutex

		http.HandleFunc("/", handleIndex)
		http.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
			handleWebSocket(w, r, &clients, &mu)
		})
		http.HandleFunc("/download", func(w http.ResponseWriter, r *http.Request) {
			handleDownload(w, r, &clients, &mu)
		})

		fmt.Println("========================================")
		fmt.Println("   Go 多线程下载工具 Web UI v1.0")
		fmt.Println("========================================")
		fmt.Printf("服务器启动在: http://localhost:%s\n", port)
		fmt.Println("请在浏览器中打开上述地址")
		fmt.Println("========================================\n")

		log.Fatal(http.ListenAndServe(":"+port, nil))
	} else {
		fmt.Println("使用方法:")
		fmt.Println("  Web UI模式: go run main_ui.go ui [端口]")
		fmt.Println("\n示例:")
		fmt.Println("  go run main_ui.go ui")
		fmt.Println("  go run main_ui.go ui 9090")
		fmt.Println("\n命令行模式请使用: go run main.go -url <URL> [选项]")
	}
}
